func TestInsertGrocery(t *testing.T) {
	db, err := Connect(context.TODO())
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close()

	id, err := InsertGrocery(context.TODO(), "apple", 5)
	if err != nil {
		t.Fatal(err)
	}
	g, err := GetGroceryByID(context.TODO(), id)
	if err != nil {
		t.Fatal(err)
	}
	if g.Name != "apple" || g.Quantity != 5 {
		t.Errorf("Expected ID %d, Name apple, Quantity 5 but got ID %d, Name %s, Quantity %d", id, g.ID, g.Name, g.Quantity)
	}
}

func TestGetGroceryByIDNotFound(t *testing.T) {
	db, err := Connect(context.TODO())
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close()

	g, err := GetGroceryByID(context.TODO(), 123)
	if g != nil || err == nil {
		t.Errorf("Expected 404 but got ID %d, Name %s, Quantity %d", g.ID, g.Name, g.Quantity)
	}
}

