	"github.com/yourusername/db"
)

func GetGrocery(w http.ResponseWriter, r *http.Request, ps httprouter.Param) {
	id, err := strconv.Atoi(ps.ByName("id"))
	if err != nil {
		http.Error(w, "Invalid ID", http.StatusBadRequest)
		return
	}

	g, err := db.GetGrocery(id)
	if err != nil {
		http.Error(w, http.StatusText(http.StatusInternalServerError), http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	err = json.NewEncoder(w).Encode(g)
	if err != nil {
		http.Error(w, http.StatusText(http.StatusInternalServerError), http.StatusInternalServerError)
		return
	}
}

func CreateGrocery(w http.ResponseWriter, r *http.Request, ps httprouter.Param) {
	var g db.Grocery
	err := json.NewDecoder(r.Body).Decode(&g)
	if err != nil {
		http.Error(w, "Invalid request body", http.StatusBadRequest)
		return
	}

	g.CreatedAt = db.NullTime{Valid: true, Time: time.Now()}
 g.UpdatedAt = db.NullTime{Valid: true, Time: time.Now()}

 createdG, err := db.CreateGrocery(g.Name, g.Quantity)
	if err != nil {
		http.Error(w, http.StatusText(http.StatusInternalServerError), http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	err = json.NewEncoder(w).Encode(createdG)
	if err != nil {
		http.Error(w, http.StatusText(http.StatusInternalServerError), http.StatusInternalServerError)
		return
	}
}

func UpdateGrocery(w http.ResponseWriter, r *http.Request, ps httprouter.Param) {
	var g db.Grocery
	id, err := strconv.Atoi(ps.ByName("id"))
	if err != nil {
		http.Error(w, "Invalid ID", http.StatusBadRequest)
		return
	}

	err = json.NewDecoder(r.Body).Decode(&g)
	if err != nil {
		http.Error(w, "Invalid request body", http.StatusBadRequest)
		return
	}

	g.ID = id
 g.CreatedAt = db.NullTime{Valid: true, Time: time.Now()}
	g.UpdatedAt = db.NullTime{Valid: true, Time: time.Now()}

 updatedG, err := db.UpdateGrocery(id, g.Name, g.Quantity)
	if err != nil {
		http.Error(w, http.StatusText(http.StatusInternalServerError), http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	err = json.NewEncoder(w).Encode(updatedG)
 if err != nil {
		http.Error(w, http.StatusText(http.StatusInternalServerError), http.StatusInternalServerError)
		return
	}
}

func DeleteGrocery(w http.ResponseWriter, r *http.Request, ps httprouter.Param) {
	id, err := strconv.Atoi(ps.ByName("id"))
	if err != nil {
		http.Error(w, "Invalid ID", http.StatusBadRequest)
		return
	}

	err = db.DeleteGrocery(id)
	if err != nil {
		http.Error(w, http.StatusText(http.StatusInternalServerError), http.StatusInternalServerError)
		return
	}

	w.WriteHeader(http.StatusNoContent)
}

