package db

import (
	"database/sql"
)

type Grocery struct {
	ID        int       `db:"id"`
	Name      string    `db:"name"`
	Quantity  int       `db:"quantity"`
	CreatedAt sql.NullTime
	UpdatedAt sql.NullTime
}

func GetGroceryByID(db *sql.DB, id int) (*Grocery, error) {
	var g Grocery
	err := db.Get(&g, "SELECT id, name, quantity, created_at, updated_at FROM groceries WHERE id = $1", id)
	if err != nil {
		return nil, err
	}
	return &g, nil
}

func ListGroceries(db *sql.DB) ([]*Grocery, error) {
	var gs []*Grocery
	err := db.Select(&gs, "SELECT id, name, quantity, created_at, updated_at FROM groceries")
	if err != nil {
		return nil, err
	}
	return gs, nil
}

func CreateGrocery(db *sql.DB, name string) (*Grocery, error) {
	var g Grocery
	err := db.Get(&g, "INSERT INTO groceries (name, quantity) VALUES ($1, $2) RETURNING id, name, quantity, created_at, updated_at", name, 0)
	if err != nil {
		return nil, err
	}
	return &g, nil
}

func UpdateGrocery(db *sql.DB, id int, name string) (*Grocery, error) {
	var g Grocery
	err := db.Get(&g, "UPDATE groceries SET name = $1, quantity =_quantity WHERE id = $2 RETURNING id, name, quantity, created_at, updated_at", name, id)
	if err != nil {
		return nil, err
	}
	return &g, nil
}

func DeleteGrocery(db *sql.DB, id int) error {
	result, err := db.Exec("DELETE FROM groceries WHERE id = $1", id)
	if err != nil {
		return err
	}
	rowsAffected, err := result.RowsAffected()
	if err != nil {
		return err
	}
	if rowsAffected == 0 {
		return sql.ErrNoRows
	}
	return nil
}

