package db

import (
	"database/sql"
)

type Grocery struct {
	ID          int
	Name        string
	Quantity    int
	CreatedAt   sql.NullTime
	UpdatedAt   sql.NullTime
}

func (g Grocery) MarshalJSON() ([]byte, error) {
	return json.Marshal(map[string]interface{}{
		"id":        g.ID,
		"name":      g.Name,
		"quantity":  g.Quantity,
		"created_at": g.CreatedAt.Time,
		"updated_at": g.UpdatedAt.Time,
	})
}

func GetGrocery(db *sql.DB, id int) (Grocery, error) {
	var g Grocery
	err := db.QueryRow("SELECT id, name, quantity, created_at, updated_at FROM groceries WHERE id = ?", id).Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt)
	if err != nil {
		return g, err
	}
	return g, nil
}

func ListGroceries(db *sql.DB) ([]Grocery, error) {
	rows, err := db.Query("SELECT id, name, quantity, created_at, updated_at FROM groceries")
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var gs []Grocery
	for rows.Next() {
		var g Grocery
		err := rows.Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt)
		if err != nil {
			return nil, err
		}
		gs = append(gs, g)
	}
	return gs, nil
}

func CreateGrocery(db *sql.DB, name string, quantity int) (int, error) {
	result, err := db.Exec("INSERT INTO groceries (name, quantity) VALUES (?, ?)", name, quantity)
	if err != nil {
		return 0, err
	}
	id, err := result.LastInsertId()
	if err != nil {
		return 0, err
	}
	return int(id), nil
}

func UpdateGrocery(db *sql.DB, id int, name string, quantity int) error {
	_, err := db.Exec("UPDATE groceries SET name = ?, quantity = ? WHERE id = ?", name, quantity, id)
	return err
}

func DeleteGrocery(db *sql.DB, id int) error {
	_, err := db.Exec("DELETE FROM groceries WHERE id = ?", id)
	return err
}

