package db

import (
	"database/sql"
	"fmt"
)

type Grocery struct {
	ID          int       `db:"id"`
	Name        string    `db:"name"`
	Quantity    int       `db:"quantity"`
	CreatedAt   time.Time `db:"created_at"`
	UpdatedAt   time.Time `db:"updated_at"`
}

const createTable = `
CREATE TABLE IF NOT EXISTS groceries (
	id SERIAL PRIMARY KEY,
	name TEXT NOT NULL,
	quantity INT NOT NULL DEFAULT 0
);
`

func Create(db *sql.DB, name string, quantity int) (Grocery, error) {
	var g Grocery
	err := db.QueryRow(`
	INSERT INTO groceries (name, quantity)
	VALUES ($1, $2)
	RETURNING id, created_at, updated_at
`, name, quantity).Scan(&g.ID, &g.CreatedAt, &g.UpdatedAt)
	if err != nil {
		return g, fmt.Errorf("create grocery: %w", err)
	}
	g.Name = name
	g.Quantity = quantity
	return g, nil
}

func Get(db *sql.DB, id int) (Grocery, error) {
	var g Grocery
	err := db.QueryRow(`
	SELECT id, name, quantity, created_at, updated_at
	FROM groceries
	WHERE id = $1
`, id).Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt)
	if err != nil {
		return g, fmt.Errorf("get grocery: %w", err)
	}
	return g, nil
}

func List(db *sql.DB) ([]Grocery, error) {
	var gs []Grocery
	rows, err := db.Query(`
	SELECT id, name, quantity, created_at, updated_at
	FROM groceries
`)
	if err != nil {
		return gs, fmt.Errorf("list groceries: %w", err)
	}
	defer rows.Close()
	for rows.Next() {
		var g Grocery
		err := rows.Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt)
		if err != nil {
			return gs, fmt.Errorf("list groceries: %w", err)
		}
		gs = append(gs, g)
	}
	return gs, nil
}

func Update(db *sql.DB, id int, name string, quantity int) (Grocery, error) {
	var g Grocery
	err := db.QueryRow(`
	UPDATE groceries
	SET name = $2, quantity = $3, updated_at = NOW()
	WHERE id = $1
	RETURNING id, name, quantity, created_at, updated_at
`, id, name, quantity).Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt)
	if err != nil {
		return g, fmt.Errorf("update grocery: %w", err)
	}
	return g, nil
}

func Delete(db *sql.DB, id int) error {
	_, err := db.Exec(`
	DELETE FROM groceries
	WHERE id = $1
`, id)
	if err != nil {
		return fmt.Errorf("delete grocery: %w", err)
	}
	return nil
}

