	defer db.Close()

	g, _ := create(db, "Apple", 10)

	req := httptest.NewRequest("DELETE", "/groceries/"+strconv.Itoa(g.ID), nil)
	resp := httptest.NewRecorder()
	DeleteGrocery(resp, req)

	if resp.Code != http.StatusNoContent {
		t.Errorf("expected status No Content, got %d", resp.Code)
	}
}

func create(db *sql.DB, name string, quantity int) (db.Grocery, error) {
	var g db.Grocery
	err := db.QueryRow(`
	INSERT INTO groceries (name, quantity)
	VALUES ($1, $2)
	RETURNING id, created_at, updated_at
`, name, quantity).Scan(&g.ID, &g.CreatedAt, &g.UpdatedAt)
	if err != nil {
		return g, fmt.Errorf("create grocery: %w", err)
	}
	g.Name = name
	g.Quantity = quantity
	return g, nil
}

