package db

import (
	"database/sql"
	"github.com/lib/pq"
)

type Grocery struct {
	ID        int
	Name      string
	Quantity  int
	CreatedAt pq.NullTime
	UpdatedAt pq.NullTime
}

func GetGroceryByID(db *sql.DB, id int) (*Grocery, error) {
	var g Grocery
	err := db.QueryRow("SELECT id, name, quantity, created_at, updated_at FROM groceries WHERE id = $1", id).Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt)
	if err != nil {
		return nil, err
	}
	return &g, nil
}

func ListGroceries(db *sql.DB) ([]*Grocery, error) {
	rows, err := db.Query("SELECT id, name, quantity, created_at, updated_at FROM groceries")
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var groceries []*Grocery
	for rows.Next() {
		var g Grocery
		err := rows.Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt)
		if err != nil {
			return nil, err
		}
		groceries = append(groceries, &g)
	}

	if err := rows.Err(); err != nil {
		return nil, err
	}

	return groceries, nil
}

func CreateGrocery(db *sql.DB, name string, quantity int) (*Grocery, error) {
	var g Grocery
	err := db.QueryRow("INSERT INTO groceries (name, quantity) VALUES ($1, $2) RETURNING id, name, quantity, created_at, updated_at", name, quantity).Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt)
	if err != nil {
		return nil, err
	}
	return &g, nil
}

func UpdateGrocery(db *sql.DB, id int, name string, quantity int) (*Grocery, error) {
	var g Grocery
	err := db.QueryRow("UPDATE groceries SET name = $1, quantity = $2 WHERE id = $3 RETURNING id, name, quantity, created_at, updated_at", name, quantity, id).Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt)
	if err != nil {
		return nil, err
	}
	return &g, nil
}

func DeleteGrocery(db *sql.DB, id int) error {
	_, err := db.Exec("DELETE FROM groceries WHERE id = $1", id)
	return err
}

