package db

import (
	"database/sql"
	"fmt"
	"time"

	_ "github.com/jackc/pgx/v4"
)

type Grocery struct {
	ID          int
	Name        string
	Quantity    int
	CreatedAt   time.Time
	UpdatedAt   time.Time
}

const (
	createGrocerySQL = `
INSERT INTO groceries (name, quantity)
VALUES ($1, $2)
RETURNING id, name, quantity, created_at, updated_at
`

	getGrocerySQL = `
SELECT id, name, quantity, created_at, updated_at
FROM groceries
WHERE id = $1
`

	updateGrocerySQL = `
UPDATE groceries
SET name = EXCLUDED.name,
    quantity = EXCLUDED.quantity
WHERE id = $1
RETURNING id, name, quantity, created_at, updated_at
`

	deleteGrocerySQL = `
DELETE FROM groceries
WHERE id = $1
RETURNING id
`

	listGroceriesSQL = `
SELECT id, name, quantity, created_at, updated_at
FROM groceries
ORDER BY id
`
)

func (d *DB) CreateGrocery(name string, quantity int) (*Grocery, error) {
	var g Grocery
	err := d.db.QueryRow(createGrocerySQL, name, quantity).Scan(
		&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt,
	)
	return &g, err
}

func (d *DB) GetGrocery(id int) (*Grocery, error) {
	var g Grocery
	err := d.db.QueryRow(getGrocerySQL, id).Scan(
		&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt,
	)
	if err == sql.ErrNoRows {
		return nil, fmt.Errorf("grocery with id %d not found", id)
	}
	return &g, err
}

func (d *DB) UpdateGrocery(id int, name string, quantity int) (*Grocery, error) {
	var g Grocery
	err := d.db.QueryRow(updateGrocerySQL, id, name, quantity).Scan(
		&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt,
	)
	if err == sql.ErrNoRows {
		return nil, fmt.Errorf("grocery with id %d not found", id)
	}
	return &g, err
}

func (d *DB) DeleteGrocery(id int) error {
	result, err := d.db.Exec(deleteGrocerySQL, id)
	if err != nil {
		return err
	}
	rowsAffected, _ := result.RowsAffected()
	if rowsAffected == 0 {
		return fmt.Errorf("grocery with id %d not found", id)
	}
	return nil
}

func (d *DB) ListGroceries() ([]*Grocery, error) {
	rows, err := d.db.Query(listGroceriesSQL)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var groceries []*Grocery
	for rows.Next() {
		var g Grocery
		err := rows.Scan(
			&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt,
		)
		if err != nil {
			return nil, err
		}
		groceries = append(groceries, &g)
	}

	return groceries, nil
}

