package handlers

import (
	"net/http"

	"github.com/gin-gonic/gin"
	"github.com/yourusername/groceryapp/db"
)

type GroceryHandler struct {
	db *db.DB
}

func NewGroceryHandler(db *db.DB) *GroceryHandler {
	return &GroceryHandler{db: db}
}

func (h *GroceryHandler) List(c *gin.Context) {
	groceries, err := h.db.ListGroceries()
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": err.Error()})
		return
	}
	c.JSON(http.StatusOK, groceries)
}

func (h *GroceryHandler) Get(c *gin.Context) {
	id := c.Param("id")
	grocery, err := h.db.GetGrocery(id)
	if err != nil {
		c.JSON(http.StatusNotFound, gin.H{"error": err.Error()})
		return
	}
	c.JSON(http.StatusOK, grocery)
}

func (h *GroceryHandler) Create(c *gin.Context) {
	var req struct {
		Name     string `json:"name" binding:"required"`
		Quantity int    `json:"quantity"`
	}
	if err := c.ShouldBindJSON(&req); err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
		return
	}
	grocery, err := h.db.CreateGrocery(req.Name, req.Quantity)
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": err.Error()})
		return
	}
	c.JSON(http.StatusCreated, grocery)
}

func (h *GroceryHandler) Update(c *gin.Context) {
	id := c.Param("id")
	var req struct {
		Name     string `json:"name" binding:"required"`
		Quantity int    `json:"quantity"`
	}
	if err := c.ShouldBindJSON(&req); err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
		return
	}
	grocery, err := h.db.UpdateGrocery(id, req.Name, req.Quantity)
	if err != nil {
		c.JSON(http.StatusNotFound, gin.H{"error": err.Error()})
		return
	}
	c.JSON(http.StatusOK, grocery)
}

func (h *GroceryHandler) Delete(c *gin.Context) {
	id := c.Param("id")
	err := h.db.DeleteGrocery(id)
	if err != nil {
		c.JSON(http.StatusNotFound, gin.H{"error": err.Error()})
		return
	}
	c.JSON(http.StatusOK, gin.H{"message": "Grocery deleted"})
}

