package db

import (
	"database/sql"
	"time"

	_ "github.com/mattn/go-sqlite3"
)

type Grocery struct {
	ID          int       `db:"id"`
	Name        string    `db:"name"`
	Quantity    int       `db:"quantity"`
	CreatedAt   time.Time `db:"created_at"`
	UpdatedAt   time.Time `db:"updated_at"`
}

var db *sql.DB

func init() {
	var err error
	db, err = sql.Open("sqlite3", "groceries.db")
	if err != nil {
		panic(err)
	}
	createTable()
}

func createTable() {
	_, err := db.Exec(`
		CREATE TABLE IF NOT EXISTS groceries (
			id INTEGER PRIMARY KEY AUTOINCREMENT,
			name TEXT NOT NULL,
			quantity INTEGER NOT NULL DEFAULT 0,
			created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
			updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
		)
	`)
	if err != nil {
		panic(err)
	}
}

func GetGrocery(id int) (*Grocery, error) {
	var g Grocery
	err := db.Get(&g, "SELECT * FROM groceries WHERE id = ?", id)
	return &g, err
}

func ListGroceries() ([]*Grocery, error) {
	var g []*Grocery
	err := db.Select(&g, "SELECT * FROM groceries")
	return g, err
}

func CreateGrocery(name string, quantity int) (*Grocery, error) {
	var g Grocery
	err := db.Get(&g, `
		INSERT INTO groceries (name, quantity)
		VALUES (?, ?)
		RETURNING id, name, quantity, created_at, updated_at
	`, name, quantity)
	return &g, err
}

func UpdateGrocery(id int, name string, quantity int) (*Grocery, error) {
	var g Grocery
	err := db.Get(&g, `
		UPDATE groceries SET name = ?, quantity = ?
		WHERE id = ?
		RETURNING id, name, quantity, created_at, updated_at
	`, name, quantity, id)
	return &g, err
}

func DeleteGrocery(id int) error {
	_, err := db.Exec("DELETE FROM groceries WHERE id = ?", id)
	return err
}

