package db

import (
	"database/sql"
)

type Grocery struct {
	ID         int       `db:"id"`
	Name       string    `db:"name"`
	Quantity   int       `db:"quantity"`
	CreatedAt  time.Time `db:"created_at"`
	UpdatedAt  time.Time `db:"updated_at"`
}

func GetGroceryByID(db *sql.DB, id int) (Grocery, error) {
	var g Grocery
	err := db.Get(&g, "SELECT * FROM groceries WHERE id = ?", id)
	return g, err
}

func ListGroceries(db *sql.DB) ([]Grocery, error) {
	var gs []Grocery
	err := db.Select(&gs, "SELECT * FROM groceries")
	return gs, err
}

func CreateGrocery(db *sql.DB, name string, quantity int) (int, error) {
	result, err := db.Exec("INSERT INTO groceries (name, quantity) VALUES ($1, $2)", name, quantity)
	if err != nil {
		return 0, err
	}
	id, _ := result.LastInsertId()
	return int(id), nil
}

func UpdateGrocery(db *sql.DB, id int, name string, quantity int) error {
	_, err := db.Exec("UPDATE groceries SET name = $1, quantity = $2 WHERE id = $3", name, quantity, id)
	return err
}

func DeleteGrocery(db *sql.DB, id int) error {
	_, err := db.Exec("DELETE FROM groceries WHERE id = ?", id)
	return err
}

