	id := chi.URLParam(r, "id")
	db := db.NewGroceriesDB(db.GetDB())
	grocery, err := db.GetGrocery(int(id))
	if err != nil {
		if err == sql.ErrNoRows {
			render.Status(r, http.StatusNotFound)
			w.Write([]byte(`{"error": "Not Found"}`))
		} else {
			render.Status(r, http.StatusInternalServerError)
			w.Write([]byte(`{"error": "Internal Server Error"}`))
		}
		return
	}

	response := &Grocery{
		ID:        grocery.ID,
		Name:      grocery.Name,
		Quantity:  grocery.Quantity,
		CreatedAt: grocery.CreatedAt.Time,
		UpdatedAt: grocery.UpdatedAt.Time,
	}

	render.JSON(w, r, response)
}

func CreateGrocery(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Name      string `json:"name" binding:"required"`
		Quantity  int    `json:"quantity" binding:"required"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		render.Status(r, http.StatusBadRequest)
		w.Write([]byte(`{"error": "Invalid request body"}`))
		return
	}

	db := db.NewGroceriesDB(db.GetDB())
	id, err := db.CreateGrocery(req.Name, req.Quantity)
	if err != nil {
		render.Status(r, http.StatusInternalServerError)
		w.Write([]byte(`{"error": "Internal Server Error"}`))
		return
	}

	response := &Grocery{
		ID:        id,
		Name:      req.Name,
		Quantity:  req.Quantity,
	}

	render.Status(r, http.StatusCreated)
	json.NewEncoder(w).Encode(response)
}

func UpdateGrocery(w http.ResponseWriter, r *http.Request) {
	id := chi.URLParam(r, "id")
	var req struct {
		Name      *string `json:"name"`
		Quantity  *int    `json:"quantity"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		render.Status(r, http.StatusBadRequest)
		w.Write([]byte(`{"error": "Invalid request body"}`))
		return
	}

	name := req.Name
	if name == nil {
		name = new(string)
	}
	quantity := req.Quantity
	if quantity == nil {
		quantity = new(int)
	}

	db := db.NewGroceriesDB(db.GetDB())
	if err := db.UpdateGrocery(int(id), *name, *quantity); err != nil {
		if err == sql.ErrNoRows {
			render.Status(r, http.StatusNotFound)
			w.Write([]byte(`{"error": "Not Found"}`))
		} else {
			render.Status(r, http.StatusInternalServerError)
			w.Write([]byte(`{"error": "Internal Server Error"}`))
		}
		return
	}

	response := &Grocery{
		ID:        int(id),
		Name:      *name,
		Quantity:  *quantity,
	}

	json.NewEncoder(w).Encode(response)
}

func DeleteGrocery(w http.ResponseWriter, r *http.Request) {
	id := chi.URLParam(r, "id")
	db := db.NewGroceriesDB(db.GetDB())
	if err := db.DeleteGrocery(int(id)); err != nil {
		if err == sql.ErrNoRows {
			render.Status(r, http.StatusNotFound)
			w.Write([]byte(`{"error": "Not Found"}`))
		} else {
			render.Status(r, http.StatusInternalServerError)
			w.Write([]byte(`{"error": "Internal Server Error"}`))
		}
		return
	}

	json.NewEncoder(w).Encode(map[string]interface{}{
		"status": "success",
	})
}

