package db

import (
	"database/sql"
)

type Grocery struct {
	ID         int
	Name       string
	Quantity   int
	CreatedAt  string
	UpdatedAt  string
}

func initializeDB(db *sql.DB) error {
	_, err := db.Exec(`
CREATE TABLE groceries (
	id INTEGER PRIMARY KEY,
	name TEXT NOT NULL,
	quantity INTEGER DEFAULT 0
)
`)
	return err
}

func InsertGrocery(db *sql.DB, name string, quantity int) error {
	_, err := db.Exec(`
INSERT INTO groceries (name, quantity)
VALUES (?, ?)
`, name, quantity)

	return err
}

func ListGroceries(db *sql.DB) ([]*Grocery, error) {
	rows, err := db.Query(`
SELECT id, name, quantity, created_at, updated_at
FROM groceries
`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var groceries []*Grocery
	for rows.Next() {
		var g Grocery
		err := rows.Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt)
		if err != nil {
			return nil, err
		}
		groceries = append(groceries, &g)
	}

	return groceries, nil
}

func GetGrocery(db *sql.DB, id int) (*Grocery, error) {
	var g Grocery
	err := db.QueryRow(`
SELECT id, name, quantity, created_at, updated_at
FROM groceries
WHERE id = ?
`, id).Scan(&g.ID, &g.Name, &g.Quantity, &g.CreatedAt, &g.UpdatedAt)
	if err == sql.ErrNoRows {
		return nil, err
	}
	if err != nil {
		return nil, err
	}

	return &g, nil
}

func UpdateGrocery(db *sql.DB, id int, quantity int) (int64, error) {
	result, err := db.Exec(`
UPDATE groceries
SET quantity = ?, updated_at = CURRENT_TIMESTAMP
WHERE id = ?
`, quantity, id)

	if err != nil {
		return 0, err
	}

	rowsAffected, err := result.RowsAffected()
	if err != nil {
		return 0, err
	}

	return rowsAffected, nil
}

func DeleteGrocery(db *sql.DB, id int) (int64, error) {
	result, err := db.Exec(`
DELETE FROM groceries
WHERE id = ?
`, id)

	if err != nil {
		return 0, err
	}

	rowsAffected, err := result.RowsAffected()
	if err != nil {
		return 0, err
	}

	return rowsAffected, nil
}

